const buildWeapon = (w, tier) => {
  const bonus = w.bonus + (tier - 1) * 3;
  const die = w.key === "Bastón doble" && tier === 4 ? 8 : w.die;
  return {
    key: tier === 1 ? w.key : w.key + TIER_SUFFIX[tier][w.g],
    trait: w.trait,
    range: w.range,
    damage: "d" + die + (bonus ? "+" + bonus : "") + " " + w.type,
    tier,
    hands: w.hands,
    ...(w.type === "mágico" ? { magic: true } : {}),
    ...(w.feature ? { feature: w.feature } : {}),
    ...(w.mods ? { mods: w.mods } : {}),
  };
};

