async function safeGet(key, shared) {
  try {
    return await storageGet(key, shared);
  } catch (e) {
    return null;
  }
}
async function safeSet(key, value, shared) {
  try {
    return await storageSet(key, value, shared);
  } catch (e) {
    return null;
  }
}

