  const performEquipFromInventory = (id, slotKind, itemName) => {
    const c = characters[id];
    if (!c) return;
    const list = getItems(c);
    const idx = list.findIndex((it) => it.name === itemName);
    if (idx === -1) return;
    const nextList = [...list];
    if ((nextList[idx].count || 1) > 1) {
      nextList[idx] = { ...nextList[idx], count: nextList[idx].count - 1 };
    } else {
      nextList.splice(idx, 1);
    }
    let patch = { f_items: JSON.stringify(nextList) };
    if (slotKind === "primary") patch.f_primary_weapon = itemName;
    else if (slotKind === "secondary") patch.f_secondary_weapon = itemName;
    else if (slotKind === "armor") {
      patch.f_armor = itemName;
      patch.armor_marked = String(ARMORS.find((a) => a.key === itemName)?.score || 0);
    }
    updateCharacterFields(id, patch);
    postCampaignEvent(id, `🎒 Equipa ${itemName} desde el inventario.`);
    setEquipPickerSlot(null);
  };

