                                            <div
                                              style={{
                                                fontSize: 11.5,
                                                color: "#9C93AD",
                                                marginTop: 2,
                                                whiteSpace: "nowrap",
                                                overflow: "hidden",
                                                textOverflow: "ellipsis",
                                              }}
                                            >
                                              {backpack.description}
                                            </div>
